function aiErrorMessage(e){const c=e?.name==='AbortError'||e?.name==='TimeoutError'?'ai_timeout':e?.message;const messages={ai_rate_limit:['AI đã chạm giới hạn sử dụng. Hãy thử lại sau.','AI usage limit reached. Try again later.','AI 使用量已達上限，請稍後再試。'],ai_timeout:['AI phản hồi quá chậm. Hãy thử lại.','AI timed out. Please retry.','AI 回應逾時，請重試。'],ai_auth:['Cấu hình khóa AI bị từ chối. Cần kiểm tra máy chủ.','AI key was rejected. Server configuration needs checking.','AI 金鑰遭拒，需檢查伺服器設定。'],ai_model_unavailable:['Mô hình AI đã cấu hình không khả dụng.','Configured AI model is unavailable.','設定的 AI 模型無法使用。'],ai_busy:['Dịch vụ AI đang bận. Hãy thử lại sau.','AI service is busy. Try again later.','AI 服務忙碌中，請稍後再試。']};return messages[c]?L(...messages[c]):L('Chưa nhận được đánh giá AI hợp lệ. Hãy thử lại. Đây không phải kết luận câu trả lời sai.','No valid AI assessment received. Retry; this does not mean your answer is wrong.','尚未收到有效的 AI 評估。請重試，這不代表答案錯誤。');}

// The cat reviews the active lesson locally, without another AI request.
let catWordIndex=-1,catTip=null;
function catWords(){const seen=new Set();return [...KW.map(w=>({en:w[0],meaning:w[1],ipa:w[2]})),...PH.map(w=>({en:w[0],meaning:w[1],ipa:w[3]}))].filter(w=>{if(!w.en||seen.has(w.en))return false;seen.add(w.en);return true;});}
function catBubble(){if(!catTip||catTip.lesson!==LID)return '';const w=catTip.word;return `<style>.cat-word-cloud{position:fixed;z-index:80;right:24px;bottom:100px;width:min(340px,calc(100vw - 32px));max-height:65vh;overflow:auto;padding:20px;background:#fffdf5;border:2px solid #d8ccef;border-radius:34px;box-shadow:0 8px 32px #45305b26}.cat-word-cloud:after{content:"";display:block;width:25px;height:14px;background:#fffdf5;border:2px solid #d8ccef;border-radius:50%;margin:10px 20px 0 auto}.cat-word-cloud p{margin:10px 0}.cat-word-cloud .row{justify-content:space-between}.pet-art[role=button]{cursor:pointer}.pet-art[role=button]:focus-visible{outline:3px solid var(--pri);outline-offset:5px}@media(max-width:600px){.cat-word-cloud{right:16px;bottom:95px;padding:16px}}
</style><aside class=cat-word-cloud data-practice role=status aria-live=polite><div class=row><b>🐾 ${E(S.pet)} · ${L('Cùng ôn từ nhé!','Let’s review!','一起複習吧！')}</b><button class=b2 data-a=catClose aria-label="${L('Đóng','Close','關閉')}">×</button></div><p class=mut>${L('Từ/cụm từ trong bài đang học','Words from the active lesson','目前課程的單字與片語')}</p><p class=english><b>${E(w.en)}</b></p>${w.ipa?`<p class=ipa>${E(w.ipa)}</p>`:''}<p><small>${L('Nghĩa','Meaning (Vietnamese)','越南文釋義')}</small><br>${E(w.meaning||'')}</p><div class=row><button class=b2 data-a=say data-t="${E(w.en)}">🔊 ${L('Nghe','Listen','聆聽')}</button><button data-a=meow>${L('Từ tiếp theo','Next word','下一個詞')}</button></div></aside>`;}
A.meow=()=>{const words=catWords();if(!words.length)return;if(catTip?.lesson!==LID)catWordIndex=-1;catWordIndex=(catWordIndex+1)%words.length;catTip={lesson:LID,word:words[catWordIndex]};petMood='wave';render();if(!pl.on&&(!mr||mr.state!=='recording'))say(catTip.word.en);};
A.catClose=()=>{catTip=null;petMood='idle';render()};
const renderBeforeCat=render;render=function(){renderBeforeCat();const app=document.querySelector('#app');if(catTip&&catTip.lesson===LID){if(app.insertAdjacentHTML)app.insertAdjacentHTML('beforeend',catBubble());else app.innerHTML+=catBubble();}};
const petBeforeReview=pet;pet=function(sz){return petBeforeReview(sz).replace('role="img" aria-label="Catty, your learning companion"',`role="button" tabindex="0" aria-label="${L('Bấm để ôn từ cùng mèo','Review words with your cat','點一下和貓咪複習單字')}"`);};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&catTip){A.catClose();return;}if((e.key==='Enter'||e.key===' ')&&e.target?.matches?.('.pet-art[data-a=meow]')){e.preventDefault();A.meow();}});
