function menuHTML(){return `<style>${menuCSS}</style><div data-practice><button class="b2 menu-launch" data-a=menuToggle aria-expanded=${menuOpen} aria-controls=site-drawer>☰ ${L('Menu','Menu','選單')}</button>${menuOpen?`<div class=menu-shade data-a=menuToggle></div><nav id=site-drawer class=site-drawer aria-label="${L('Menu chính','Main menu','主選單')}"><h2>🐾 CattySpeaking</h2><button class=b2 data-a=menuToggle>${L('Đóng menu','Close menu','關閉選單')} ×</button>${homeItems().map(([id,label])=>`<button class=b2 data-a=menuSection data-section=${id} ${view==='home'&&homeSection===id?'aria-current=page':''}>${label}</button>`).join('')}<button class=b2 data-a=go data-v=theory>${L('Cơ sở thiết kế','Design rationale','設計依據')}</button><button class=b2 data-a=go data-v=pet>${L('Nhà của mèo','Cat’s home','貓咪的家')}</button><button class=b2 data-a=go data-v=progress>${L('Tiến trình','Progress','學習進度')}</button></nav>`:''}</div>`;}
