// A quiet learning flow: question, answer, feedback, then continue.
const simpleNames=()=>[L('Thử trả lời','Try an answer','試著回答'),L('Nghe hội thoại','Listen to the dialogue','聆聽對話'),L('Học từ và cụm từ','Learn useful phrases','學習實用片語'),L('Kiểm tra nghe hiểu','Check understanding','檢查理解'),L('Luyện trả lời','Practise answering','練習回答'),L('Thử tình huống mới','Try a new situation','嘗試新情境'),L('Nhìn lại bài học','Reflect on your lesson','回顧課程')];
const captureBeforeSimple=captureUI;captureUI=function(k){return captureBeforeSimple(k).replaceAll(L('Ghi âm','Record','錄音'),L('Bắt đầu nói','Start speaking','開始說話'));};
task=function(k){const c=currentTask(k),hasAnswer=!!(TX[k]||'').trim();return `<section class=card data-practice><p class=mut>${E(goalText(c))}</p><button class=b2 data-a=say data-t="${E(c.q)}">🔊 ${L('Nghe câu hỏi','Hear the question','聽問題')}</button><h2 class=english>${E(c.q)}</h2>${captureUI(k)}<label for=tx-${k}>${L('Câu trả lời của bạn','Your answer','你的回答')}</label><input type=text id=tx-${k} data-k=${k} value="${E(TX[k]||'')}" placeholder="${L('Nói hoặc gõ bằng tiếng Anh','Speak or type in English','請用英文說或輸入')}"><p class=mut>${L('Có thể sửa chữ nếu máy nghe nhầm.','Edit the text if recognition is wrong.','若辨識有誤，可修改文字。')}</p><button data-a=chk data-k=${k} ${pending[k]?'disabled':''}>${pending[k]?L('Đang nhận xét…','Checking…','評估中…'):L('Xem nhận xét','Get feedback','查看回饋')}</button>${msgs[k]?`<p role=status>${E(msgs[k])}</p>`:''}${feedbackHTML(k)}<details class=practice-help ${usedHelp[k]?'open':''}><summary>${L('Cần gợi ý?','Need a hint?','需要提示嗎？')}</summary>${supportHTML(k,c)}<button class=b2 data-a=say data-t="${E(c.tk.sample)}">🔊 ${L('Nghe câu mẫu','Hear the model','聽範例')}</button><button class=b2 data-a=practiceHint data-k=${k}>${L('Xem gợi ý','Show a hint','顯示提示')}</button>${usedHelp[k]?`<p class=hint>${E(c.tk.sample)}</p>`:''}</details>${fb[k]?`<button class=b2 data-a=newTry data-k=${k}>↺ ${L('Thử lại','Try again','再試一次')}</button>`:''}</section>`;};
const lessonBeforeSimple=vLesson;
vLesson=function(){const s=STEPS[step],names=simpleNames(),head=`<div data-practice class=simple-heading><p class=mut>${E(TITLE)} · ${L('Bước','Step','步驟')} ${step+1}/7</p><progress max=7 value=${step+1} aria-label="${L('Tiến trình bài học','Lesson progress','課程進度')}"></progress><h1>${names[step]}</h1></div>`;
 if(['A','E','F'].includes(s)){const k={A:'a',E:'e1',F:'f'}[s];return head+task(k)+`<div class=simple-next data-practice>${s==='A'&&!S.tries.a?`<button class=b2 data-a=cant>${L('Tôi cần nghe mẫu trước','I need to hear a model first','我想先聽範例')}</button>`:''}<button data-a=next ${!gate()?'disabled':''}>${L('Tiếp tục','Continue','繼續')} ↵</button></div><details class=practice-help data-practice><summary>${L('Luyện thêm','Extra practice','額外練習')}</summary><button class=b2 data-a=prev ${step===0?'disabled':''}>${L('Quay lại','Back','返回')}</button><button class=b2 data-a=fluencyOpen>${L('Luyện nội dung quen','Practise familiar content','練習熟悉內容')}</button>${s==='F'?`<button class=b2 data-a=conversationOpen>${L('Hội thoại nhiều lượt','Multi-turn conversation','多輪對話')}</button>`:''}</details>`;}
 let html=lessonBeforeSimple();html=html.replace(/<div class=lesson-companion>[\s\S]*?<div class=steps>[\s\S]*?<\/div>/,head).replace(/<h2>[A-G]\. ([^<]*)<\/h2>/g,'');
 if(s==='B'){html=html.replace(/<div class=row><label><input type=checkbox[\s\S]*?data-a=nosub>[\s\S]*?<\/button>/,m=>`<details class=practice-help><summary>${L('Phụ đề và tùy chọn nghe','Subtitles and listening options','字幕與聆聽選項')}</summary>${m}</details>`);html=html.replace(/<div class=card (hidden)?><h3>Từ & cụm từ chính<\/h3>([\s\S]*?)<\/div><\/div>/,(_,hidden,body)=>`<details class=card ${hidden||''}><summary>${L('Từ và IPA','Words and IPA','單字與音標')}</summary>${body}</details></div>`);}
 return html;
};
const homeBeforeSimple=vHome;vHome=function(){if(homeSection!=='current')return homeBeforeSimple();return `<div data-practice class=simple-home><h1>${L('Học một chút mỗi ngày','A little practice every day','每天練習一點點')}</h1>${pet(170)}<div class=card><p class=mut>${L('Bài đang học','Your current lesson','目前學習的課程')}</p><h2>${E(TITLE)}</h2><p>${L('Nghe · Nói · Thử lại','Listen · Speak · Try again','聆聽 · 口說 · 再試一次')}</p><button data-a=go data-v=lesson>${L('Học tiếp','Continue learning','繼續學習')} ↵</button></div></div>`;};
const renderBeforeSimple=render;render=function(){renderBeforeSimple();const app=document.querySelector('#app');const css=`<style>.simple-home{max-width:640px;margin:auto;text-align:center}.simple-home .pet-art{margin:12px auto}.simple-home h1{font-size:1.55rem}.simple-home .card{text-align:left}.simple-home .card>button,.simple-next>button:last-child{width:100%}.simple-heading{max-width:760px;margin:auto}.simple-heading h1{font-size:1.6rem}.simple-heading progress{width:100%;height:12px;accent-color:var(--pri)}.practice-help{margin:18px 0;padding:14px;border:1px solid var(--bd);border-radius:14px;background:var(--card)}.practice-help summary{cursor:pointer;font-weight:600}.practice-help[open] summary{margin-bottom:14px}.grid>details{align-self:start}.simple-next{display:grid;gap:12px;margin:20px 0}#app .cat-word-cloud{max-height:50vh}.simple-home .pet-art{cursor:pointer}</style>`;if(app.insertAdjacentHTML)app.insertAdjacentHTML('afterbegin',css);else app.innerHTML=css+app.innerHTML;};
// Stream interim recognition into the existing answer field without rerendering each word.
startASR=function(k){if(!SR)return;try{rc=new SR();rc.lang='en-US';rc.interimResults=true;rc.continuous=true;rc.onresult=e=>{const t=Array.from(e.results,r=>r[0].transcript).join(' ').trim();if(t){TX[k]=t;ASRT[k]=t;ED[k]=false;const input=document.querySelector('#tx-'+k);if(input)input.value=t;else render();const btn=document.querySelector(`[data-a=chk][data-k="${k}"]`);if(btn)btn.disabled=false;}};rc.onerror=e=>{msgs[k]=L('Chưa nhận được chữ. Bạn có thể gõ lại câu đã nói.','No transcript received. You can type your answer.','尚未收到辨識文字，可自行輸入回答。');};rc.start();}catch{rc=null;}};
render();

