let draftLesson=null,draftScript='',draftOriginal='',draftEditing=false;
const label3=a=>S.lang==='en'?a[1]:S.lang==='zh-TW'?a[2]:a[0];
const priorHomeItems=homeItems;homeItems=()=>[['current',L('Bài hiện tại','Current lesson','目前課程')],['basics',L('Chủ đề cơ bản','Basic topics','基礎主題')],...priorHomeItems().filter(x=>!['current','device'].includes(x[0])),['about',L('Giới thiệu app','About the app','關於本程式')]];
const deviceHome=vHome;
vHome=function(){
 if(homeSection==='basics')return `<div data-practice><h1>${L('Chọn chủ đề và bắt đầu','Choose a topic and start','選擇主題並開始')}</h1><p class=mut>${L('Bài mẫu soạn sẵn, dùng được khi AI bận. Hội thoại tiếng Anh kèm nghĩa tiếng Việt.','Prepared lessons work without AI. English dialogues include Vietnamese meanings.','預先編寫的課程不需 AI。英文對話附越南文翻譯。')}</p><div class=strand-grid><button class=b2 data-a=useL data-id=fruit>🍎 ${L('Mua trái cây','Buying fruit','買水果')}</button>${BASIC_TOPICS.map(x=>`<button class=b2 data-a=basicPreview data-id=${x.id}>${x.emoji} ${E(label3(x.names))}</button>`).join('')}</div></div>`;
 if(homeSection==='about'){const keep=homeSection;homeSection='device';const device=deviceHome();homeSection=keep;return `<div data-practice><h1>${L('Giới thiệu CattySpeaking','About CattySpeaking','關於 CattySpeaking')}</h1><div class=card><p>${L('Luyện giao tiếp tiếng Anh cơ bản: nghe mẫu, thử nói, xem gợi ý và tự trả lời. Mèo giúp ôn từ trong bài.','Practise basic English: listen, speak, use hints, and answer independently. Your cat helps review lesson words.','練習基礎英語：聆聽、試說、使用提示，再獨立回答。貓咪協助複習課程詞彙。')}</p><p class=mut>${L('Đây là sản phẩm thử nghiệm cho môn học, chưa có nghiên cứu chứng minh hiệu quả.','This is a course prototype without demonstrated learning effectiveness.','這是課程原型，尚無研究證明學習成效。')}</p></div><details class=practice-help><summary>${L('Cơ sở thiết kế','Design rationale','設計依據')}</summary>${vTheory()}</details><details class=practice-help><summary>${L('Thiết bị và âm thanh','Device and audio','裝置與音訊')}</summary>${device}</details><details class=practice-help><summary>${L('Dữ liệu và giới hạn','Data and limitations','資料與限制')}</summary><p>${L('Tạo bài và đánh giá ý nghĩa gửi văn bản tới Gemini. Nhận xét phát âm chỉ gửi bản ghi khi bạn bấm gửi và đồng ý. App không lưu bản ghi trên máy chủ; dịch vụ AI xử lý dữ liệu theo điều khoản của họ. Không gửi thông tin cá nhân.','Text is sent to Gemini for lesson creation and meaning feedback. Audio is sent only when you explicitly request audio feedback and agree. The app does not store recordings on its server; provider terms apply. Do not send personal information.','建立課程與語意回饋會將文字傳送至 Gemini。只有同意並要求語音回饋時才傳送錄音。本程式不在伺服器儲存錄音；服務供應商條款適用。請勿傳送個人資料。')}</p></details></div>`;}
 if(homeSection==='draft'&&draftLesson)return draftView();return deviceHome();
};
const menuPrior=menuHTML;menuHTML=function(){let h=menuPrior();h=h.replace(/<button class=b2 data-a=menuToggle>[\s\S]*?<\/button>/,'').replace(/<button class=b2 data-a=go data-v=theory>[\s\S]*?<\/button>/,'');return h.replace('</nav>',`<button class=b2 data-a=menuToggle>${L('Đóng menu','Close menu','關閉選單')} ×</button></nav>`);};
function scriptOf(l){return l.T.map(t=>`${t[0]==='S'?'Partner':'You'}: ${t[1]}`).join('\n');}
function showDraft(l){draftLesson=l;draftOriginal=scriptOf(l);draftScript=draftOriginal;draftEditing=false;homeSection='draft';view='home';render();}
A.basicPreview=d=>{const x=BASIC_TOPICS.find(x=>x.id===d.id);if(!x)return;const l=normLesson(x.lesson);l.title=label3(x.names);l.id=x.id;l.language='vi';l.preset=true;showDraft(l);};
function draftView(){return `<div data-practice><h1>${L('Xem trước hội thoại','Preview dialogue','預覽對話')}</h1><p>${E(draftLesson.title)}</p><p class=mut>${L('Đọc lại trước khi học. Bạn có thể dùng đoạn này hoặc chỉnh sửa.','Review it before learning. Use this dialogue or edit it.','學習前請先檢查。你可以使用這段對話或修改內容。')}</p>${draftEditing?`<label for=draft-script>${L('Nội dung hội thoại tiếng Anh','English dialogue','英文對話')}</label><textarea id=draft-script rows=12 style="width:100%;font:inherit" maxlength=3000>${E(draftScript)}</textarea><p class=mut>${L('Sau khi sửa, AI cần tạo lại nghĩa, IPA và bài tập cho khớp. Bản cũ không bị ghi đè nếu tạo lại lỗi.','After editing, AI rebuilds translations, IPA and exercises. A failed rebuild keeps the previous version.','修改後需由 AI 重新建立翻譯、音標與題目；失敗時保留舊版本。')}</p>`:draftLesson.T.map(t=>`<div class=bubble><b>${t[0]==='S'?L('Đối tác','Partner','對方'):L('Bạn','You','你')}</b><p>${E(t[1])} <button class=b2 data-a=say data-t="${E(t[1])}">🔊</button></p><small>${E(t[2])}</small></div>`).join('')}<p role=status>${E(msgs.topic||'')}</p><div class=row><button data-a=draftAccept ${BUSY||draftScript!==draftOriginal?'disabled':''}>${L('Học đoạn này','Practise this dialogue','練習這段對話')} ↵</button><button class=b2 data-a=draftEdit ${BUSY?'disabled':''}>${L('Chỉnh sửa nội dung','Edit content','修改內容')}</button>${draftEditing?`<button class=b2 data-a=draftRebuild ${BUSY?'disabled':''}>${L('Tạo lại bài từ script đã sửa','Rebuild from edited script','依修改內容重建課程')}</button>`:''}<button class=b2 data-a=draftCancel ${BUSY?'disabled':''}>${L('Quay lại','Back','返回')}</button></div></div>`;}
A.draftEdit=()=>{draftEditing=true;render()};
A.draftCancel=()=>{draftLesson=null;homeSection='basics';render()};
A.draftRebuild=()=>{TOP=`Create a beginner English lesson based on this reviewed dialogue. Preserve its intent and facts.\n${draftScript}`;genLesson();};
A.draftAccept=()=>{if(!draftLesson||draftScript!==draftOriginal||BUSY)return;const l=draftLesson,old=S.custom.findIndex(x=>x.id===l.id);if(old>=0)S.custom[old]=l;else{if(!l.preset&&S.custom.filter(x=>!x.preset).length>=8){msgs.topic=L('Đã đủ 8 bài riêng. Hãy xóa bớt trước.','Eight custom lessons already saved. Delete one first.','已儲存八個自訂課程，請先刪除一個。');render();return;}S.custom.push(l);}save();useLesson(l.id);draftLesson=null;view='lesson';step=1;render();};
genLesson=async function(){const request=(TOP||'').trim();if(request.length<8){msgs.topic=L('Hãy mô tả tình huống kỹ hơn.','Describe the situation in more detail.','請更詳細描述情境。');render();return;}if(BUSY)return;BUSY=true;msgs.topic=L('Đang tạo bản xem trước…','Creating a preview…','正在建立預覽…');render();try{const r=await fetch('/api/topic',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({request:request.slice(0,3500),language:S.lang}),signal:AbortSignal.timeout(55000)});const j=await r.json();if(j.unsuitable)throw new Error(j.reason||'unsuitable');if(!r.ok||!j.lesson)throw new Error('unavailable');const l=normLesson(j.lesson);if(l.T.length<4||!l.R.a||!l.R.e1||!l.R.f||!l.Q.length||!l.KW.length||!l.PH.length||l.SC.length<2)throw new Error('invalid_lesson');l.language=S.lang;l.id='c'+Date.now();msgs.topic='';showDraft(l);}catch{msgs.topic=L('Chưa tạo được bài. Bạn có thể thử lại hoặc chọn chủ đề cơ bản. Bản nháp cũ được giữ lại.','Could not create the lesson. Retry or choose a basic topic. Any previous draft is retained.','無法建立課程。請重試或選擇基礎主題，原草稿會保留。');}finally{BUSY=false;render();}};
document.addEventListener('input',e=>{if(e.target?.id==='draft-script'){draftScript=e.target.value;const b=document.querySelector('[data-a=draftAccept]');if(b)b.disabled=draftScript!==draftOriginal;}});
render();

// Audio feedback is opt-in, uses the actual clip, and never scores pronunciation from ASR.
const audioFeedback={},audioPending={};
async function wavForClip(url){const r=await fetch(url),b=await r.arrayBuffer();const AudioCtx=window.AudioContext||window.webkitAudioContext;if(!AudioCtx)throw new Error('audio_conversion');const ctx=new AudioCtx();try{const audio=await ctx.decodeAudioData(b);if(audio.duration>20||audio.duration<.4)throw new Error('audio_duration');const n=Math.floor(audio.duration*16000),out=new ArrayBuffer(44+n*2),v=new DataView(out),write=(o,s)=>Array.from(s).forEach((c,i)=>v.setUint8(o+i,c.charCodeAt(0)));write(0,'RIFF');v.setUint32(4,36+n*2,true);write(8,'WAVE');write(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,16000,true);v.setUint32(28,32000,true);v.setUint16(32,2,true);v.setUint16(34,16,true);write(36,'data');v.setUint32(40,n*2,true);const channels=Array.from({length:audio.numberOfChannels},(_,i)=>audio.getChannelData(i));for(let i=0;i<n;i++){const pos=Math.floor(i*audio.sampleRate/16000);let value=channels.reduce((sum,c)=>sum+(c[pos]||0),0)/channels.length;value=Math.max(-1,Math.min(1,value));v.setInt16(44+i*2,value<0?value*32768:value*32767,true);}let binary='';const bytes=new Uint8Array(out);for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(binary);}finally{await ctx.close();}}
function pronunciationUI(k,reference){const f=audioFeedback[k],same=!!f&&f.clip===rec[k];return `<div data-practice><details class=practice-help><summary>${L('Nhờ AI nghe phát âm','Ask AI to listen to pronunciation','請 AI 聽發音')}</summary><p>${L('Phản hồi thử nghiệm từ âm thanh thật, không phải điểm phát âm chuẩn hóa. Chỉ gửi đoạn dưới 20 giây khi bạn đồng ý.','Experimental feedback from actual audio, not a validated pronunciation score. Only send a clip under 20 seconds if you agree.','根據實際音訊提供試驗性回饋，並非標準化發音評分。只有同意時才傳送 20 秒內的錄音。')}</p><label><input type=checkbox id=audio-consent-${k}> ${L('Tôi đồng ý gửi bản ghi này tới Gemini để nhận xét.','I agree to send this recording to Gemini for feedback.','我同意將這段錄音傳送至 Gemini 以取得回饋。')}</label><button class=b2 data-a=pronounce data-k=${k} data-reference="${E(reference)}" ${!rec[k]||audioPending[k]?'disabled':''}>${audioPending[k]?L('Đang nghe…','Listening…','正在聆聽…'):L('Gửi bản ghi để nhận xét','Send recording for feedback','傳送錄音以取得回饋')}</button>${!rec[k]?`<p>${L('Ghi âm và bấm Dừng trước.','Record and press Stop first.','請先錄音並按停止。')}</p>`:''}${same?`<div role=status>${f.error?`<p>${E(f.error)}</p>`:`<p><b>${L('AI nghe được','AI heard','AI 聽到')}: ${E(f.heard||L('Chưa nghe rõ','Unclear','不清楚'))}</b></p><p>${E(f.good)}</p><p>${E(f.improve)}</p>${f.practice?`<p>${E(f.practice)} <button class=b2 data-a=say data-t="${E(f.practice)}">🔊</button></p>`:''}`}</div>`:''}</details></div>`;}
A.pronounce=async d=>{const k=d.k,clip=rec[k],lesson=LID;if(!clip||audioPending[k])return;if(!document.querySelector('#audio-consent-'+k)?.checked){toast(L('Hãy đồng ý gửi bản ghi trước.','Please agree to send the recording first.','請先同意傳送錄音。'));return;}audioPending[k]=true;render();try{const audio=await wavForClip(clip);const r=await fetch('/api/pronunciation',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({audio,mimeType:'audio/wav',reference:d.reference,language:S.lang,consent:true}),signal:AbortSignal.timeout(28000)});const j=await r.json();if(!r.ok)throw new Error(j.error);if(lesson===LID&&rec[k]===clip)audioFeedback[k]={...j,clip};}catch(e){if(lesson===LID&&rec[k]===clip)audioFeedback[k]={clip,error:e?.message==='audio_duration'?L('Hãy ghi một câu từ 0,4 đến 20 giây.','Record one sentence lasting 0.4–20 seconds.','請錄製 0.4–20 秒的一句話。'):L('Chưa phân tích được âm thanh. Không có kết luận về phát âm; bạn có thể thử lại.','Audio could not be assessed. No pronunciation judgement was made; you may retry.','無法評估音訊。未做發音判斷，可以重試。')};}finally{delete audioPending[k];render();}};
const recBeforeAudio=recUI;recUI=function(k,tip){const reference=k.startsWith('c')?PH[Number(k.slice(1))]?.[0]:null;return recBeforeAudio(k,tip)+(reference?pronunciationUI(k,reference):'');};
const captureBeforeAudio=captureUI;captureUI=function(k){return captureBeforeAudio(k)+(currentTask(k)?.tk?.sample?pronunciationUI(k,currentTask(k).tk.sample):'');};
const taskBeforeAudio=task;task=function(k){return taskBeforeAudio(k);};
render();

// Guided two-person roleplay: synthetic partner turns + real learner recordings.
let roleplay=null;
function newRoleplay(){return {lesson:LID,turns:T.map(t=>[...t]),title:TITLE,index:0,state:'ready',rate:.85,clips:{},durations:{},stream:null,recorder:null,started:0,limit:20,token:0,error:'',replayIndex:0,player:null,timer:null};}
function stopRoleplay(release=true){if(!roleplay)return;roleplay.token++;clearTimeout(roleplay.timer);roleplay.player?.pause();if(roleplay.recorder?.state==='recording'){roleplay.recorder.onstop=null;roleplay.recorder.stop();}if(TTS)speechSynthesis.cancel();if(release){roleplay.stream?.getTracks().forEach(t=>t.stop());roleplay.stream=null;}if(roleplay.state!=='done')roleplay.state='paused';}
function clearRoleplay(){stopRoleplay();if(roleplay)Object.values(roleplay.clips).forEach(u=>URL.revokeObjectURL(u));roleplay=null;}
function roleplaySpeak(text,done){if(!TTS){roleplay.error=L('Trình duyệt không có giọng đọc.','Speech playback is unavailable.','瀏覽器無法播放語音。');roleplay.state='paused';roleplay.stream?.getTracks().forEach(t=>t.stop());roleplay.stream=null;render();return;}const id=roleplay.token,u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=roleplay.rate;if(voice)u.voice=voice;u.onend=()=>{if(roleplay&&roleplay.token===id)done()};u.onerror=()=>{if(roleplay&&roleplay.token===id){roleplay.state='paused';roleplay.stream?.getTracks().forEach(t=>t.stop());roleplay.stream=null;roleplay.error=L('Chưa phát được giọng đọc. Hãy bấm Tiếp tục.','Could not play speech. Press Resume.','無法播放語音，請按繼續。');render();}};speechSynthesis.cancel();speechSynthesis.speak(u);}
function runRoleplayTurn(){const p=roleplay;if(!p||p.lesson!==LID)return;if(p.index>=p.turns.length){p.state='done';p.stream?.getTracks().forEach(t=>t.stop());p.stream=null;render();return;}p.error='';const turn=p.turns[p.index];if(turn[0]==='S'){p.state='partner';render();roleplaySpeak(turn[1],()=>{p.index++;runRoleplayTurn()});}else{if(!p.stream){p.state='paused';p.error=L('Bấm Tiếp tục và cho phép micro.','Press Resume and allow microphone access.','請按繼續並允許麥克風。');render();return;}const index=p.index,chunks=[],m=new MediaRecorder(p.stream);p.recorder=m;p.state='recording';p.started=Date.now();m.ondataavailable=e=>{if(e.data?.size)chunks.push(e.data)};m.onstop=()=>{clearTimeout(p.timer);p.recorder=null;if(roleplay!==p)return;const blob=new Blob(chunks,{type:m.mimeType});if(blob.size<1500){p.stream?.getTracks().forEach(t=>t.stop());p.stream=null;p.state='paused';p.error=L('Chưa có bản ghi đủ dài. Bấm Tiếp tục để thử lượt này.','Recording is too short. Press Resume to retry this turn.','錄音太短，請按繼續重試這一輪。');render();return;}if(p.clips[index])URL.revokeObjectURL(p.clips[index]);p.clips[index]=URL.createObjectURL(blob);p.durations[index]=Math.round((Date.now()-p.started)/100)/10;p.index++;runRoleplayTurn();};m.start();p.timer=setTimeout(()=>{if(m.state==='recording')m.stop()},p.limit*1000);render();}}
A.roleplayOpen=()=>{stopPl();stopCapture();if(!roleplay||roleplay.lesson!==LID){clearRoleplay();roleplay=newRoleplay();}view='roleplay';render();};
A.roleplayStart=async()=>{const p=roleplay;if(!p||['partner','recording','replay','permission'].includes(p.state))return;if(!TTS||!window.MediaRecorder||!navigator.mediaDevices){p.error=L('Cần trình duyệt hỗ trợ giọng đọc và ghi âm.','This mode requires speech playback and recording support.','此模式需要語音播放與錄音支援。');render();return;}p.state='permission';render();try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});if(roleplay!==p||view!=='roleplay'||p.state!=='permission'){stream.getTracks().forEach(t=>t.stop());return;}p.stream=stream;p.token++;runRoleplayTurn();}catch{p.state='paused';p.error=L('Chưa mở được micro. Bạn vẫn có thể nghe hội thoại mẫu ở bài học.','Microphone unavailable. You can still listen to the lesson model.','無法開啟麥克風，仍可在課程中聆聽範例。');render();}};
A.roleplayStopTurn=()=>{if(roleplay?.recorder?.state==='recording')roleplay.recorder.stop()};
A.roleplayPause=()=>{stopRoleplay();render()};
A.roleplayReset=()=>{clearRoleplay();roleplay=newRoleplay();render()};
A.roleplaySpeed=(d,t)=>{if(roleplay)roleplay.rate=Number(t.value)};
A.roleplayLimit=(d,t)=>{if(roleplay)roleplay.limit=Number(t.value)};
function replayRoleplay(){const p=roleplay;if(!p)return;const i=p.replayIndex;if(i>=p.turns.length){p.state='done';render();return;}const turn=p.turns[i];p.index=i;p.state='replay';render();const id=p.token,next=()=>{if(roleplay===p&&p.token===id){p.replayIndex++;replayRoleplay()}};if(turn[0]==='S')roleplaySpeak(turn[1],next);else if(p.clips[i]){const audio=new Audio(p.clips[i]);p.player=audio;audio.onended=next;audio.onerror=()=>{p.error=L('Không phát được bản ghi.','Could not play this recording.','無法播放錄音。');p.state='paused';render()};audio.play().catch(()=>audio.onerror());}else{p.error=L('Lượt này chưa có bản ghi. Hãy luyện lại để nghe đủ hai vai.','This turn has no recording. Practise again for a complete replay.','這一輪尚無錄音，請重新練習以完整重播。');p.state='paused';render();}}
A.roleplayReplay=()=>{if(!roleplay)return;stopRoleplay();roleplay.token++;roleplay.error='';roleplay.replayIndex=0;replayRoleplay()};
function roleplayView(){const p=roleplay;if(!p)return '';const active=['partner','recording','permission','replay'].includes(p.state),recording=p.state==='recording',elapsed=Object.values(p.durations).reduce((a,b)=>a+b,0),status={ready:L('Sẵn sàng','Ready','準備就緒'),partner:L('A đang nói — hãy nghe','A is speaking — listen','A 正在說話，請聆聽'),recording:L('Đến lượt bạn — đang ghi âm','Your turn — recording','輪到你，正在錄音'),paused:L('Đã tạm dừng','Paused','已暫停'),permission:L('Đang mở micro…','Opening microphone…','正在開啟麥克風…'),done:L('Đã kết thúc','Finished','已完成'),replay:L('Đang nghe lại hai vai','Replaying both roles','正在重播雙方對話')};return `<div data-practice><h1>${L('Đóng vai cùng AI','Roleplay with AI','與 AI 角色扮演')}</h1><p>${E(p.title)}</p><p class=mut>${L('Theo script: A là giọng tổng hợp, B là bạn. Đây chưa phải AI trả lời tự do. Ghi âm chỉ ở trình duyệt, không gửi lên máy chủ trong chế độ này.','Scripted practice: A uses synthetic speech; you are B. This is not free conversation. Recordings stay in the browser in this mode.','依劇本練習：A 為合成語音，你是 B。這不是自由對話。此模式的錄音只保留於瀏覽器。')}</p><div class=card><div class=row><label>${L('Tốc độ A','A’s speed','A 的語速')} <select data-a=roleplaySpeed ${active?'disabled':''}>${[.7,.85,1].map((r,i)=>`<option value=${r} ${p.rate===r?'selected':''}>${[L('Chậm','Slow','慢'),L('Vừa','Normal','一般'),L('Nhanh','Faster','快')][i]}</option>`).join('')}</select></label><label>${L('Tối đa mỗi lượt của bạn','Maximum per learner turn','每輪回答上限')} <select data-a=roleplayLimit ${active?'disabled':''}>${[10,20,30].map(n=>`<option value=${n} ${p.limit===n?'selected':''}>${n}s</option>`).join('')}</select></label></div><p role=status><b>${status[p.state]}</b> · ${Math.min(p.index+1,p.turns.length)}/${p.turns.length}</p><p>${L('Thời gian bạn đã nói','Your recorded speaking time','你的錄音時間')}: ${elapsed.toFixed(1)}s ${recording?'<span id=roleplay-clock></span>':''}</p>${p.error?`<p role=alert>${E(p.error)}</p>`:''}<div class=row>${!active&&p.state!=='done'?`<button data-a=roleplayStart>${p.state==='ready'?L('Bắt đầu đối thoại','Start roleplay','開始對話'):L('Tiếp tục','Resume','繼續')}</button>`:''}${recording?`<button data-a=roleplayStopTurn>⏹ ${L('Nói xong — đến lượt A','Done — A’s turn','說完了，換 A')}</button>`:''}${active?`<button class=b2 data-a=roleplayPause>${L('Tạm dừng','Pause','暫停')}</button>`:''}${!active&&Object.keys(p.clips).length?`<button data-a=roleplayReplay>▶ ${L('Nghe lại cuộc đối thoại','Replay the conversation','重播對話')}</button>`:''}${!active?`<button class=b2 data-a=roleplayReset>${L('Luyện lại từ đầu','Start again','重新練習')}</button>`:''}</div><p class=mut>${L('Có thể bấm nói xong sớm, tạm dừng hoặc thử lại. Không chấm tốc độ và không trừ xu. Khi tải lại trang, bản ghi sẽ mất.','Finish early, pause or retry anytime. No speed score or coin penalty. Reloading clears recordings.','可提早結束、暫停或重試。不評分速度，也不扣金幣。重新載入會清除錄音。')}</p></div><div class=roleplay-script>${p.turns.map((t,i)=>`<div class="bubble ${t[0]==='L'?'learner':''} ${i===p.index?'role-current':''}"><b>${t[0]==='S'?L('A · Giọng AI','A · AI voice','A · AI 語音'):L('B · Bạn','B · You','B · 你')} ${p.clips[i]?'✓':''}</b><p>${E(t[1])}</p><details><summary>${L('Nghĩa và IPA','Meaning and IPA','翻譯與音標')}</summary><p>${E(t[2])}</p><p class=ipa>${E(t[3]||'')}</p></details></div>`).join('')}</div><button class=b2 data-a=go data-v=lesson>${L('Về bài học','Back to lesson','返回課程')}</button><style>.roleplay-script{display:flex;flex-direction:column;gap:14px;margin:20px 0}.role-current{outline:3px solid #8b75df;background:#f0ebff}.roleplay-script .bubble{width:min(90%,600px)}</style></div>`;}
const goBeforeRoleplay=A.go;A.go=d=>{stopRoleplay();goBeforeRoleplay(d)};
const useBeforeRoleplay=useLesson;useLesson=function(...args){clearRoleplay();useBeforeRoleplay(...args)};
const lessonBeforeRoleplay=vLesson;vLesson=function(){return lessonBeforeRoleplay()+`<details class=practice-help data-practice><summary>${L('Đối thoại hai vai','Two-person roleplay','雙人角色扮演')}</summary><p>${L('Web nói vai A, bạn nói vai B; sau đó nghe lại cả hai.','The app speaks A; you speak B. Replay both afterwards.','程式說 A，你說 B，之後可重播雙方。')}</p><button class=b2 data-a=roleplayOpen>${L('Đóng vai cùng AI','Roleplay with AI','與 AI 角色扮演')}</button></details>`;};
const draftBeforeRoleplay=draftView;draftView=function(){return draftBeforeRoleplay()+`<div data-practice><button class=b2 data-a=draftRoleplay ${BUSY||draftScript!==draftOriginal?'disabled':''}>${L('Luyện đoạn này theo hai vai','Roleplay this dialogue','以雙人模式練習這段對話')}</button></div>`};
A.draftRoleplay=()=>{if(BUSY||draftScript!==draftOriginal)return;A.draftAccept();if(!draftLesson)A.roleplayOpen()};
const renderBeforeRoleplay=render;render=function(){if(view==='roleplay'){const app=document.querySelector('#app');app.innerHTML=menuHTML()+languageBar()+roleplayView();document.documentElement.lang=S.lang||'vi';}else renderBeforeRoleplay();};
setInterval(()=>{const e=document.querySelector('#roleplay-clock');if(e&&roleplay?.state==='recording')e.textContent=` · ${Math.floor((Date.now()-roleplay.started)/1000)}s / ${roleplay.limit}s`;},1000);
render();

// Practice levels describe support, not a certified CEFR result.
S.practiceLevel=Number.isInteger(S.practiceLevel)?Math.max(0,Math.min(2,S.practiceLevel)):0;
const practiceLevels=()=>[[L('1 · Làm quen','1 · Getting started','1 · 入門'),L('Nghe mẫu, nhìn câu và nói theo.','Listen, see the model, and try speaking.','聽範例、看句子並試著說。')],[L('2 · Giao tiếp','2 · Communicating','2 · 溝通'),L('Nghe câu hỏi, tự trả lời; mở gợi ý khi cần.','Hear the question, answer, and open hints if needed.','聽問題並回答，需要時開啟提示。')],[L('3 · Tự đối thoại','3 · Independent roleplay','3 · 獨立對話'),L('Không hiện sẵn lượt của bạn; tự diễn đạt rồi nghe lại.','Your lines stay hidden; answer in your own words and replay.','隱藏你的台詞，自行表達後再重播。')]];
function practiceLevelUI(){return `<div data-practice class=card><h2>${L('Chọn cấp luyện','Choose a practice level','選擇練習級別')}</h2><p class=mut>${L('Chọn theo mức tự tin. Có thể đổi bất cứ lúc nào; không phải bài xếp hạng trình độ.','Choose by confidence. Change anytime; this is not a proficiency placement test.','依信心選擇，隨時可更改；這不是能力分級測驗。')}</p>${practiceLevels().map(([name,desc],i)=>`<p><button class=${S.practiceLevel===i?'':'b2'} data-a=practiceLevel data-n=${i} aria-pressed=${S.practiceLevel===i}>${name}</button><br><small>${desc}</small></p>`).join('')}</div>`;}
A.practiceLevel=d=>{S.practiceLevel=Math.max(0,Math.min(2,Number(d.n)));adaptive().level=[0,1,3][S.practiceLevel];adaptive().streak=0;adaptive().offer=false;save();render()};
const homeBeforeAudience=vHome;vHome=function(){let html=homeBeforeAudience();if(['basics','about'].includes(homeSection))html+=practiceLevelUI();if(homeSection==='about')html=`<div data-practice><div class=card><h2>${L('App này dành cho ai?','Who is this app for?','誰適合使用？')}</h2><p>${L('Người muốn luyện đối thoại tiếng Anh ngắn để dùng ngay: khách du lịch, người chuẩn bị ra nước ngoài, người cần giao tiếp đời thường hoặc muốn tập nói riêng trước khi nói với người thật. Không cần học theo một giáo trình dài để bắt đầu một tình huống.','For people who want short, practical English conversations: travellers, people preparing to go abroad, everyday communicators, and anyone wanting private practice before speaking with others. You can start a situation without following a long course.','適合想練習短篇實用英語對話的人：旅客、準備出國者、需要日常溝通者，或想先獨自練習再與真人交談的人。可直接從情境開始，不必先完成長篇課程。')}</p><h3>${L('Mục tiêu','Goal','目標')}</h3><p>${L('Sau một buổi ngắn, thử nghe và đáp lại trong một tình huống cụ thể: gọi món, hỏi đường, nhận phòng hoặc trao đổi ở hiệu thuốc. Ưu tiên truyền đạt được ý, biết hỏi lại và thử nói bằng cách khác.','After a short session, practise understanding and responding in one situation: ordering, asking directions, checking in, or talking at a pharmacy. Focus on meaning, asking for clarification, and trying alternative expressions.','在短時間內練習理解並回應一個情境，例如點餐、問路、入住或在藥局溝通。重點是表達意思、請對方說明，以及嘗試不同說法。')}</p><p class=mut>${L('Không hứa học nhanh sẽ nói thành thạo. App không thay thế giáo viên, giáo trình toàn diện hay giao tiếp thật. Hội thoại hiệu thuốc chỉ để luyện ngôn ngữ, không tư vấn chữa bệnh.','No promise of quick fluency. This app does not replace teachers, a complete curriculum, or real interaction. Pharmacy dialogues practise language and do not provide medical advice.','不承諾快速達到流利程度。本程式不取代教師、完整課程或真實交流。藥局對話僅用於語言練習，不提供醫療建議。')}</p></div></div>`+html;return html;};
const acceptBeforeLevel=A.draftAccept;A.draftAccept=()=>{acceptBeforeLevel();if(!draftLesson){adaptive().level=[0,1,3][S.practiceLevel];save();}};
const roleplayNewBeforeLevel=newRoleplay;newRoleplay=function(){return {...roleplayNewBeforeLevel(),level:S.practiceLevel}};
const roleplayViewBeforeLevel=roleplayView;roleplayView=function(){if(!roleplay)return '';let html=roleplayViewBeforeLevel();const p=roleplay;if(p.state!=='replay'&&p.level>0){html=html.replace(/<div class="bubble learner[\s\S]*?<\/div>/g,m=>{if(p.level===1)return `<details class=practice-help><summary>${L('Lượt của bạn · Mở gợi ý','Your turn · Show hint','你的回合 · 開啟提示')}</summary>${m}</details>`;const mark=m.includes('✓')?'✓':'';return `<div class="bubble learner"><b>${L('B · Bạn','B · You','B · 你')} ${mark}</b><p>${L('Tự trả lời câu trước bằng tiếng Anh. Nghe lại để xem lời mình đã nói.','Answer the previous question in English. Replay to hear what you said.','請用英文回答上一個問題，重播時可聽到你的回答。')}</p></div>`;});}return `<div data-practice><p class=mut>${practiceLevels()[p.level][0]}</p></div>`+html;};
render();

const topicDescriptions={
 'basic-milk-tea':['Bạn đến quán trà sữa để gọi một ly mang đi. Bạn sẽ tập chọn đồ uống, yêu cầu nửa lượng đường và trả lời câu hỏi của nhân viên. Đọc hội thoại trước, sau đó đóng vai khách hàng để luyện nói.','You visit a milk tea shop to order a takeaway drink. Practise choosing a drink, asking for half sugar, and answering the server. Read the dialogue, then play the customer.','你到奶茶店買外帶飲料。練習選飲料、要求半糖，並回答店員的問題。先閱讀對話，再扮演顧客練習。'],
 'basic-cafe':['Bạn ghé quán cà phê và gọi một ly cà phê đá. Bạn sẽ tập nói món mình muốn, chọn nóng hay đá và lịch sự từ chối gọi thêm. Sau khi xem nội dung, hãy thử trả lời nhân viên bằng giọng của mình.','You stop at a café and order an iced coffee. Practise ordering, choosing hot or iced, and politely declining anything else. After reviewing the dialogue, answer the server in your own voice.','你到咖啡店點一杯冰咖啡。練習點餐、選擇冷熱，並禮貌地婉拒加點。看完內容後，用自己的聲音回答店員。'],
 'basic-directions':['Bạn đang đi du lịch và cần tìm ga tàu. Bạn sẽ tập hỏi vị trí, hỏi có xa không và cảm ơn người chỉ đường. Hội thoại có chỉ dẫn đi thẳng, rẽ trái và thời gian đi bộ để bạn luyện nghe hiểu.','You are travelling and need to find the train station. Practise asking where it is, asking about distance, and thanking the person. Listen for directions and walking time.','你旅行時需要找到火車站。練習詢問位置、距離並表達感謝。對話包含直走、左轉及步行時間，可練習聽懂指示。'],
 'basic-hotel':['Bạn đến khách sạn để nhận phòng đã đặt. Bạn sẽ tập yêu cầu nhận phòng, xác nhận phòng đơn và hỏi vị trí thang máy. Đây là đoạn ngắn để chuẩn bị cho một cuộc trao đổi ở quầy lễ tân.','You arrive at a hotel to check in. Practise requesting check-in, confirming a single room, and asking where the elevator is. This short dialogue prepares you for a reception-desk exchange.','你到飯店辦理入住。練習提出入住要求、確認單人房並詢問電梯位置。這段短對話協助你準備與櫃台人員交流。'],
 'basic-pharmacy':['Bạn đến hiệu thuốc và muốn trao đổi với dược sĩ vì đau bụng. Bạn sẽ tập mô tả triệu chứng, trả lời có bị sốt hay không và hỏi chỗ chờ. Đây chỉ là bài luyện ngôn ngữ, không hướng dẫn chọn thuốc, chẩn đoán hay điều trị.','You visit a pharmacy to talk with a pharmacist about a stomachache. Practise describing a symptom, answering a fever question, and asking where to wait. This is language practice, not diagnosis or treatment advice.','你因肚子痛到藥局與藥師交流。練習描述症狀、回答是否發燒並詢問等候位置。這僅是語言練習，不提供選藥、診斷或治療建議。'],
 fruit:['Bạn mua táo và chuối ở quầy trái cây. Bạn sẽ tập nói món và số lượng, hỏi giá và nghe tổng tiền. Sau khi đọc hội thoại, thử đổi cách nói mà vẫn giữ đúng ý cần mua.','You buy apples and bananas at a fruit stall. Practise items, quantities, prices and the total. Read the dialogue, then express the same request in your own words.','你在水果攤買蘋果與香蕉。練習品項、數量、詢價及總金額。閱讀對話後，試著用自己的說法表達相同需求。']};
const homeBeforeTopicCards=vHome;vHome=function(){if(homeSection!=='basics')return homeBeforeTopicCards();return `<div data-practice><h1>${L('Chủ đề cơ bản','Basic topics','基礎主題')}</h1><p>${L('Chọn một tình huống. Đọc hội thoại rồi bấm Bắt đầu luyện.','Choose a situation, read the dialogue, then start practising.','選擇情境，閱讀對話後開始練習。')}</p>${practiceLevelUI()}${[{id:'fruit',emoji:'🍎',names:['Mua trái cây','Buying fruit','買水果']},...BASIC_TOPICS].map(x=>`<article class=card><h2>${x.emoji} ${E(label3(x.names))}</h2><p>${E(label3(topicDescriptions[x.id]))}</p><button class=b2 data-a=${x.id==='fruit'?'fruitPreview':'basicPreview'} data-id=${x.id}>${L('Xem hội thoại','Read dialogue','查看對話')} →</button></article>`).join('')}</div>`;};
A.fruitPreview=()=>showDraft({...SAMPLE,id:'fruit',preset:true});
const acceptBeforeFruit=A.draftAccept;A.draftAccept=()=>{if(draftLesson?.id==='fruit'&&draftScript===draftOriginal&&!BUSY){useLesson('fruit');draftLesson=null;view='lesson';step=1;adaptive().level=[0,1,3][S.practiceLevel];save();render();}else acceptBeforeFruit();};
const draftBeforeStart=draftView;draftView=function(){return draftBeforeStart().replaceAll(L('Học đoạn này','Practise this dialogue','練習這段對話'),L('Bắt đầu luyện','Start practising','開始練習'));};
render();
